void drawDuckBody(glm::mat4 duck) {
	glUniformMatrix4fv(spFur->u("M"), 1, false, glm::value_ptr(duck));

	glEnableVertexAttribArray(spFur->a("vertex"));
	glVertexAttribPointer(spFur->a("vertex"), 4, GL_FLOAT, false, 0, vertices_Body);
	glEnableVertexAttribArray(spFur->a("normal"));
	glVertexAttribPointer(spFur->a("normal"), 4, GL_FLOAT, false, 0, vertexNormals_Body);
	glEnableVertexAttribArray(spFur->a("texCoord0"));
	glVertexAttribPointer(spFur->a("texCoord0"), 2, GL_FLOAT, false, 0, texCoords_Body);

	glUniform1f(spFur->u("maxFurLength"), 0.1);
	glUniform1f(spFur->u("maxLayer"), 100);
	
	glUniform1i(spFur->u("textureMap0"), 0);
	glActiveTexture(GL_TEXTURE0);
	glBindTexture(GL_TEXTURE_2D, texFur);

	glUniform1i(spFur->u("textureMap1"), 0);
	glActiveTexture(GL_TEXTURE1);
	glBindTexture(GL_TEXTURE_2D, texYellowDuck);

	glDrawArraysInstanced(GL_TRIANGLES, 0, vertexCountBody, 100);
	glDisableVertexAttribArray(spFur->a("vertex"));
	glDisableVertexAttribArray(spFur->a("normal"));
	glDisableVertexAttribArray(spFur->a("texCoord0"));
}

